# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, N, E, M, P, K = "Lucas", "Amparo", "Noura", "Denise", "Maribel", "Pepe", "Paco"
D = [
("#", "Escena 1 · Lunes 16 de noviembre, 8:15 · Sala de reuniones, Onda", "장면 1 · 11월 16일 월요일 오전 8시 15분 · 온다, 회의실"),
(None, "Llueve sobre los naranjos. En la mesa, dos correos impresos y una caja de etiquetas recién llegada de la imprenta. Maribel ha traído su carpeta azul, la de las auditorías.", "오렌지 밭 위로 비가 내린다. 탁자 위에는 출력한 메일 두 통과 인쇄소에서 막 도착한 라벨 상자 하나. 마리벨은 감사 때마다 들고 다니는 파란 파일철을 가져왔다."),
(A, "Te leo el primero. «Denise Carrasco, BuildMart. Llegada a Onda: lunes 30 de noviembre. Duración de la auditoría: dos días».", "첫 번째 거 읽어 줄게요. '드니스 카라스코, 빌드마트. 온다 도착: 11월 30일 월요일. 감사 기간: 이틀.'"),
(L, "Y el segundo: «Eng. Noura Al-Qahtani, inspectora de calidad. Visita a fábrica: del martes 1 al jueves 3 de diciembre».", "그리고 두 번째: '누라 알카흐타니 엔지니어, 품질 검사관. 공장 방문: 12월 1일 화요일부터 3일 목요일까지.'"),
(M, "O sea, que el martes tenemos a las dos a la vez. Una en el almacén y otra en el laboratorio.", "그러니까 화요일엔 두 사람이 동시에 있는 거네요. 한 명은 창고에, 한 명은 실험실에."),
(A, "No hay manera de mover ninguna. Denise ya tiene los billetes y la saudí viene desde Riad.", "둘 다 옮길 방법이 없어요. 드니스는 벌써 비행기표를 끊었고, 사우디 검사관은 리야드에서 오고요."),
(L, "Entonces nos repartimos. Tú te quedas con Denise, que ya la conoces de Atlanta. Yo, con la inspectora.", "그럼 나눠요. 당신은 드니스를 맡아요. 애틀랜타에서 이미 만났으니까. 나는 검사관을 맡을게요."),
(A, "Me parece bien. Pero Maribel no se puede partir en dos.", "좋아요. 근데 마리벨은 둘로 쪼갤 수가 없잖아요."),
(M, "Puedo, si me dejáis los papeles preparados con el fin de no perder tiempo buscando nada. Cada lote, cada ensayo, cada firma.", "할 수 있어요. 아무것도 찾느라 시간 낭비하지 않게 서류만 다 준비해 두면요. 로트마다, 시험마다, 서명마다."),
(L, "¿Qué nos falta?", "뭐가 부족해요?"),
(M, "Para BuildMart, repetir el ensayo de caída con las cantoneras nuevas. En Atlanta se nos desconchó una esquina, ¿os acordáis?", "빌드마트 쪽은 새 모서리 보호대로 낙하 시험을 다시 해야 해요. 애틀랜타에서 모서리 하나가 깨졌잖아요, 기억나죠?"),
(A, "Como para olvidarlo. Denise lo apuntó en rojo.", "잊을 수가 있나요. 드니스가 빨간 펜으로 적었는데."),
(M, "Y para la saudí, todo lo del certificado: fichas técnicas, registros de producción y las etiquetas en árabe. Que acaban de llegar.", "그리고 사우디 쪽은 인증서 관련 전부요. 기술 자료, 생산 기록, 그리고 아랍어 라벨. 방금 도착했어요."),
(None, "Lucas abre la caja de etiquetas. Las mira al derecho y al revés. Para él, es un dibujo bonito.", "루카스가 라벨 상자를 연다. 똑바로도 보고 거꾸로도 본다. 그에게는 예쁜 그림일 뿐이다."),
(L, "Yo no sé leer ni una letra. ¿Quién las ha revisado?", "나는 한 글자도 못 읽어요. 누가 검토했어요?"),
(M, "La imprenta dice que copió el texto que nos mandaron de Riad. Tal cual.", "인쇄소 말로는 리야드에서 보내 준 문구를 그대로 복사했대요. 토씨 하나 안 바꾸고."),
(L, "Se las enseñaré a Tariq por videollamada. Por si acaso.", "타리크한테 화상 통화로 보여 줄게요. 혹시 모르니까."),
(A, "¿Y cuándo se las vas a enseñar? Tariq está en Riad y allí el viernes no trabaja nadie.", "언제 보여 줄 건데요? 타리크는 리야드에 있고, 거긴 금요일엔 아무도 일 안 해요."),
(L, "Allí la semana laboral va de domingo a jueves. Se lo mando hoy y me contesta mañana, si Dios quiere, como dice él.", "거긴 일요일부터 목요일까지 일해요. 오늘 보내면 내일 답이 오겠죠. 그 사람 말대로, 신의 뜻이라면."),
(M, "Pues apuntadlo en la lista. Si no está en la lista, no existe.", "그럼 목록에 적어 둬요. 목록에 없으면 없는 거예요."),
(L, "(escribe) «Etiquetas en árabe: revisión por Tariq». Ya existe.", "(적으며) '아랍어 라벨: 타리크 검토.' 이제 있어요."),
(P, "(entra con el casco en la mano) ¿Quién ha dicho «por si acaso»? Esa frase me da miedo un lunes.", "(안전모를 손에 들고 들어오며) 누가 '혹시 모르니까'라고 했어? 월요일에 그 말 들으면 겁나."),
(A, "Pepe, la semana del treinta vienen dos auditoras. Necesitamos el horno tres limpio como una patena.", "페페, 30일 주에 감사관이 두 명 와요. 3호기를 반짝반짝하게 해 놔야 해요."),
(P, "El tres siempre está limpio. Lo que no está es libre. Y las auditoras quieren ver la línea funcionando, no un museo.", "3호기는 늘 깨끗해. 깨끗하지 않은 게 아니라 비어 있지가 않은 거지. 그리고 감사관들은 박물관이 아니라 돌아가는 라인을 보고 싶어 해."),
(L, "Mejor. Que vean cómo trabajamos de verdad.", "그게 더 좋아요. 우리가 진짜 어떻게 일하는지 보라고 하죠."),

("#", "Escena 2 · Lunes 30 de noviembre, 10:00 · Almacén de producto terminado", "장면 2 · 11월 30일 월요일 오전 10시 · 완제품 창고"),
(None, "Denise Carrasco recorre los pasillos con una tablet y una cinta métrica. Amparo camina a su lado. Paco espera junto a la máquina de caída.", "드니스 카라스코가 태블릿과 줄자를 들고 통로를 걷는다. 암파로가 옆에서 걷는다. 파코는 낙하 시험기 옆에서 기다리고 있다."),
(E, "Empecemos por lo que falló en Atlanta. ¿Qué cambiaron?", "애틀랜타에서 실패한 것부터 시작하죠. 뭘 바꿨어요?"),
(A, "Cuatro cantoneras de cartón reforzado por palé, como pide su manual. Y una cantonera interior en cada caja, que no pedía nadie.", "매뉴얼대로 팔레트마다 강화 판지 모서리 보호대 네 개요. 그리고 상자마다 안쪽 보호대를 하나씩 넣었어요. 아무도 요구하지 않았지만요."),
(E, "¿Y eso por qué?", "그건 왜요?"),
(A, "Porque la esquina que se rompió no se rompió por fuera. Se rompió dentro de la caja, contra la otra pieza.", "깨진 모서리는 밖에서 깨진 게 아니었거든요. 상자 안에서 다른 타일에 부딪혀 깨졌어요."),
(E, "Hmm. Eso no está en el manual. Pero tiene sentido. Paco, ¿verdad? Suéltela.", "흠. 그건 매뉴얼에 없네요. 하지만 일리가 있어요. 파코 씨, 맞죠? 떨어뜨려 보세요."),
(K, "¿Desde qué altura, señora?", "몇 높이에서요?"),
(E, "La del protocolo. Esquina, arista y cara plana. Tres caídas por caja, tres cajas.", "프로토콜대로요. 모서리, 모서리선, 평면. 상자마다 세 번, 상자 세 개."),
(None, "Nueve golpes secos. Paco abre las cajas con el cúter y coloca las piezas sobre una mesa. Denise las revisa con una linterna, una por una.", "둔탁한 소리가 아홉 번. 파코가 커터로 상자를 열고 타일을 탁자 위에 늘어놓는다. 드니스가 손전등을 비춰 하나씩 살핀다."),
(E, "Ni una marca. Bien. Ahora la trazabilidad. Elijo un palé al azar: este.", "자국 하나 없네요. 좋아요. 이제 추적성이요. 팔레트 하나를 무작위로 고를게요. 이거요."),
(A, "Antes de la trazabilidad, ¿quiere ver el peso de las cajas? En Atlanta nos dijo que no podían pasar de sesenta libras.", "추적성 전에 상자 무게도 보시겠어요? 애틀랜타에서 60파운드를 넘으면 안 된다고 하셨죠."),
(E, "Sí. Paco, ¿una báscula?", "네. 파코 씨, 저울 있어요?"),
(K, "Aquí la tiene. Veintiséis kilos y cuatrocientos gramos.", "여기요. 26킬로 400그램이에요."),
(E, "Unas cincuenta y ocho libras. Justo por debajo. ¿Y la etiqueta de la caja?", "약 58파운드네요. 딱 아래예요. 상자 라벨은요?"),
(A, "En inglés y en español, con el lote y el calibre bien grandes. Lo pidió un colocador de Texas.", "영어와 스페인어로, 로트와 칼리브레를 크게 넣었어요. 텍사스의 시공팀장이 요청한 거예요."),
(E, "Eso tampoco está en el manual. Ustedes tienen la costumbre de hacer más de lo que se les pide.", "그것도 매뉴얼에 없네요. 여러분은 요구받은 것보다 더 하는 버릇이 있군요."),
(A, "Es que el manual lo escribe usted. Las cajas las abre el colocador.", "매뉴얼은 당신이 쓰지만, 상자는 시공 기술자가 열잖아요."),
(A, "Lote M-41, tono cuatro, calibre uno. Fabricado el diecinueve de noviembre en el horno tres.", "로트 M-41, 톤 4, 칼리브레 1. 11월 19일 3호기에서 생산."),
(E, "Demuéstremelo.", "증명해 보세요."),
(A, "(escanea el código y abre el registro en el ordenador) Aquí está: hora de entrada en el horno, temperatura máxima, el control de Maribel y quién lo embaló.", "(코드를 스캔하고 컴퓨터에서 기록을 연다) 여기 있어요. 가마 투입 시각, 최고 온도, 마리벨의 검사, 그리고 누가 포장했는지까지."),
(E, "Muy bien. (gira el palé) Pero aquí hay un problema. El código de barras de este lado está tapado por el fleje.", "아주 좋아요. (팔레트를 돌리며) 근데 여기 문제가 있네요. 이쪽 면 바코드가 결속 밴드에 가려져 있어요."),
(K, "¡Uy! Ese lo até yo. El fleje se ha corrido al mover el palé.", "어이쿠! 그건 제가 묶었어요. 팔레트를 옮기다가 밴드가 밀렸네요."),
(E, "En nuestro centro de distribución, un lector que no lee son doscientos cincuenta dólares. No es personal, es el manual.", "우리 물류센터에선 스캐너가 못 읽으면 250달러예요. 개인적인 감정이 아니라 매뉴얼이 그래요."),
(A, "Lo entiendo. ¿Lo podemos corregir hoy mismo?", "이해해요. 오늘 바로 고쳐도 될까요?"),
(E, "Lo anoto como observación menor, no como no conformidad. Si mañana me enseña la acción correctiva por escrito, se queda en eso.", "중대 부적합이 아니라 경미한 지적 사항으로 적을게요. 내일 시정 조치를 서면으로 보여 주면 그걸로 끝이에요."),
(A, "Mañana a primera hora la tiene. Paco, ¿cuánto tardarías en mover el fleje cinco centímetros en todos los palés?", "내일 아침 일찍 드릴게요. 파코, 모든 팔레트에서 밴드를 5센티 옮기는 데 얼마나 걸려요?"),
(K, "Si me dejan una plantilla de cartón para marcar la altura, ni un minuto por palé.", "높이 표시용 판지 틀만 하나 주시면 팔레트당 1분도 안 걸려요."),
(E, "¿Lo ve? Eso es lo que quiero ver: que el operario entienda el porqué. En muchas fábricas el operario no sabe para qué sirve el código.", "보셨죠? 내가 보고 싶은 게 그거예요. 작업자가 이유를 이해하는 것. 많은 공장에선 작업자가 바코드가 왜 있는지도 몰라요."),
(K, "Para que en Atlanta no nos cobren, señora. Eso lo entiende cualquiera.", "애틀랜타에서 우리한테 돈 안 물리게 하려고요. 그건 누구나 알죠."),
(E, "(sonríe, por fin) Me gusta este señor.", "(마침내 미소 지으며) 이분 마음에 드네요."),

("#", "Escena 3 · Martes 1 a miércoles 2 de diciembre · Laboratorio de calidad y nave del horno tres", "장면 3 · 12월 1일 화요일~2일 수요일 · 품질 실험실과 3호기 작업동"),
(None, "En el laboratorio, la ingeniera Noura Al-Qahtani lleva una abaya azul marino y unas gafas de seguridad. Habla un español limpio, con algún giro valenciano de sus años en la Politécnica.", "실험실. 누라 알카흐타니 엔지니어는 남색 아바야에 보안경을 썼다. 발렌시아 공대 시절에 익힌 발렌시아식 말투가 가끔 섞인 깔끔한 스페인어를 쓴다."),
(N, "Buenos días. Antes de empezar, una cosa: yo no vengo a ver lo que ustedes me quieran enseñar. Vengo a ver lo que hay.", "안녕하세요. 시작하기 전에 하나만요. 저는 여러분이 보여 주고 싶은 걸 보러 온 게 아닙니다. 있는 그대로를 보러 왔어요."),
(L, "Me parece justo. Tiene acceso a toda la fábrica.", "공정하네요. 공장 어디든 보셔도 됩니다."),
(N, "Gracias. Entonces, primero, las muestras. No las de la vitrina. Las que salgan ahora mismo del horno.", "감사합니다. 그럼 먼저 샘플부터요. 진열장에 있는 거 말고요. 지금 가마에서 막 나오는 걸로요."),
(P, "Ahora mismo salen placas de sesenta por ciento veinte para Miami. Las de Arena de Najd entran esta tarde.", "지금은 마이애미용 60×120 판이 나오고 있어요. 아레나 데 나지드는 오늘 오후에 들어가요."),
(N, "Entonces esta tarde. Yo elijo las piezas. Diez, al azar, de la línea.", "그럼 오늘 오후로 하죠. 타일은 제가 고릅니다. 라인에서 무작위로 열 장."),
(None, "A las cinco, Noura marca diez piezas con un rotulador. En el laboratorio, Maribel las pesa, las mide y las mete en agua hirviendo para el ensayo de absorción.", "5시, 누라가 마커로 타일 열 장에 표시한다. 실험실에서 마리벨이 무게를 달고, 치수를 재고, 흡수율 시험을 위해 끓는 물에 넣는다."),
(M, "Se mantienen dos horas en ebullición y después se dejan enfriar en el agua. Luego se pesan otra vez.", "두 시간 동안 끓이고, 그다음 물속에서 식힙니다. 그런 뒤 무게를 다시 재요."),
(N, "Lo conozco, gracias. ¿Y la planitud?", "알고 있어요, 감사합니다. 평탄도는요?"),
(M, "Se mide en el centro y en las esquinas. Tenemos una tolerancia interna más estrecha que la norma.", "가운데와 모서리에서 잽니다. 저희 내부 허용 오차는 규격보다 더 엄격해요."),
(N, "¿Cuánto más estrecha?", "얼마나 더 엄격한가요?"),
(M, "La mitad. Lo que se sale de nuestra tolerancia va a segunda calidad, aunque la norma lo aceptara.", "절반이요. 저희 허용 오차를 벗어나면, 규격으로는 통과하더라도 2등급으로 돌려요."),
(N, "(lo apunta) Eso me interesa. Lo quiero ver en los registros de los últimos tres meses, no en una frase.", "(받아 적으며) 그거 흥미롭네요. 말로 말고 최근 3개월 기록으로 보고 싶어요."),
(M, "Aquí los tiene. Por semanas.", "여기 있습니다. 주별로요."),
(L, "Mientras los revisa, ¿le puedo hacer una pregunta? ¿Por qué estudió en Valencia y no en Estados Unidos, como tantos ingenieros?", "검토하시는 동안 질문 하나 해도 될까요? 다른 엔지니어들처럼 미국이 아니라 왜 발렌시아에서 공부하셨어요?"),
(N, "Porque mi beca era para materiales cerámicos, y para eso el sitio es Castellón y Valencia. Hice las prácticas en un laboratorio de esmaltes, a veinte kilómetros de aquí.", "제 장학금이 세라믹 재료 분야였는데, 그 분야라면 카스테욘과 발렌시아죠. 실습은 여기서 20킬로미터 떨어진 유약 연구소에서 했어요."),
(L, "Entonces conoce el sector mejor que yo.", "그럼 저보다 이 업계를 더 잘 아시겠네요."),
(N, "Conozco los defectos mejor que usted. Que no es lo mismo.", "결함은 당신보다 더 잘 알죠. 그건 같은 게 아니에요."),
(None, "Noura vuelve a los registros y los hojea en silencio diez minutos más. Lucas no sabe dónde poner las manos. Por fin, ella cierra la carpeta.", "누라가 다시 기록으로 돌아가 10분 동안 말없이 넘긴다. 루카스는 손을 어디에 둘지 모른다. 마침내 그녀가 파일철을 덮는다."),
(N, "Los registros son correctos. Ahora, las etiquetas en árabe.", "기록은 정확합니다. 이제 아랍어 라벨이요."),
(L, "Antes de las etiquetas, ¿quiere ver la resistencia a la rotura? Maribel ya tiene las piezas en la prensa.", "라벨 전에 파괴 강도 시험도 보시겠어요? 마리벨이 벌써 타일을 프레스에 올려놨어요."),
(M, "Se aplica la carga en el centro, poco a poco, hasta que la pieza rompe. Y se anota el valor.", "가운데에 하중을 조금씩 가해서 타일이 깨질 때까지 누릅니다. 그리고 수치를 기록하고요."),
(N, "(mira la lectura) Muy por encima del mínimo. Como esperaba. Lo que me preocupa nunca es la pieza. Es todo lo que la rodea.", "(수치를 보며) 최소 기준보다 한참 위네요. 예상대로예요. 제가 걱정하는 건 늘 타일이 아니에요. 타일을 둘러싼 모든 거죠."),
(L, "¿Todo lo que la rodea?", "타일을 둘러싼 모든 거라뇨?"),
(N, "La etiqueta, la caja, el palé, el barco, el adhesivo y el colocador. Una pieza perfecta mal colocada es una pieza mala.", "라벨, 상자, 팔레트, 배, 접착제, 그리고 시공 기술자요. 완벽한 타일도 잘못 깔면 나쁜 타일이 됩니다."),
(L, "Aquí están. El texto nos lo mandó su departamento.", "여기 있습니다. 문구는 그쪽 부서에서 보내 준 거예요."),
(N, "(mira una, luego otra, y frunce el ceño) Señor Ferrer, esto no se puede leer.", "(하나를 보고, 또 하나를 보고는 눈살을 찌푸린다) 페레르 씨, 이건 읽을 수가 없어요."),
(L, "¿Cómo que no? Si es el texto que nos mandaron.", "읽을 수 없다니요? 보내 주신 문구 그대로인데요."),
(N, "El texto, sí. Pero está escrito de izquierda a derecha, y las letras están sueltas, como si fueran mayúsculas una detrás de otra. El árabe se escribe de derecha a izquierda y las letras se unen.", "문구는 맞아요. 하지만 왼쪽에서 오른쪽으로 쓰여 있고 글자가 다 떨어져 있어요. 대문자를 하나씩 늘어놓은 것처럼요. 아랍어는 오른쪽에서 왼쪽으로 쓰고 글자를 이어서 씁니다."),
(L, "O sea, que es como si escribiéramos «ADNO» en vez de «ONDA», y encima con letras recortadas una a una.", "그러니까 우리가 'ONDA'를 'ADNO'로 거꾸로 쓰고, 그것도 글자를 하나씩 오려 붙인 셈이네요."),
(N, "(casi sonríe) Peor. Hay palabras que, separadas, significan otra cosa. Aquí pone algo parecido a «frágil», pero alguien de Riad leería una tontería.", "(웃을 뻔하며) 더 나빠요. 떼어 놓으면 다른 뜻이 되는 단어도 있어요. 여기는 '깨지기 쉬움' 비슷한 말인데, 리야드 사람은 엉뚱한 말로 읽을 거예요."),
(L, "Tiene que ver con el programa de la imprenta, ¿verdad? No con el texto.", "인쇄소 프로그램 문제죠? 문구 문제가 아니라."),
(N, "Exacto. Se trata de un problema muy común: muchos programas no saben escribir en árabe. De ahí que siempre pida ver la etiqueta impresa, no el archivo.", "맞아요. 아주 흔한 문제예요. 아랍어를 제대로 못 쓰는 프로그램이 많거든요. 그래서 저는 늘 파일이 아니라 인쇄된 라벨을 보자고 합니다."),
(L, "Lo corregimos esta semana. Y antes de imprimir, se la mando a usted en papel, escaneada.", "이번 주 안에 고치겠습니다. 그리고 인쇄하기 전에 종이로 뽑아서 스캔해 보내 드릴게요."),
(N, "A mí y a Tariq. Que lo lea alguien que lo lee todos los días.", "저하고 타리크한테요. 매일 읽는 사람이 읽어야죠."),
(None, "Miércoles por la mañana. Nave del horno tres. Noura observa el embalaje de un palé de Arena de Najd. Pepe le explica el proceso.", "수요일 아침. 3호기 작업동. 누라가 아레나 데 나지드 팔레트 포장을 지켜본다. 페페가 공정을 설명한다."),
(P, "Las placas grandes van de canto, en caballetes de madera tratada. Nada de ponerlas planas, que se parten por su propio peso.", "큰 판은 처리된 나무 받침대에 세워서 실어요. 눕히면 안 돼요. 자기 무게 때문에 쪼개지거든요."),
(N, "Bien. Ahora, una pregunta que no está en ningún manual: ¿qué pasa con este plástico a cincuenta grados?", "좋아요. 이제 어느 매뉴얼에도 없는 질문 하나요. 50도에서 이 비닐은 어떻게 되죠?"),
(P, "(mira el film) Pues... se ablanda. Y si se ablanda, se suelta.", "(필름을 보며) 음… 물러지죠. 물러지면 풀리고요."),
(N, "En el puerto de Dammam, en agosto, un contenedor cerrado pasa de sesenta por dentro. He visto palés llegar como un acordeón.", "8월의 담맘 항에서는 닫힌 컨테이너 안이 60도를 넘어요. 아코디언처럼 찌그러져 도착한 팔레트를 본 적이 있어요."),
(L, "¿Qué nos recomienda?", "어떻게 하라고 권하시겠어요?"),
(N, "No recomiendo marcas. Recomiendo pruebas. Metan un palé en una cámara caliente durante tres días y vean qué queda.", "브랜드를 권하진 않아요. 시험을 권하죠. 팔레트 하나를 사흘 동안 고온실에 넣어 두고 뭐가 남는지 보세요."),
(P, "Cámara no tenemos. Pero tenemos la zona de secaderos, que a la salida va a más de cincuenta.", "고온실은 없어요. 하지만 건조기 구역이 있어요. 출구 쪽은 50도가 넘어요."),
(N, "(lo piensa) Sirve, si se mide la temperatura cada hora y se apunta. Con el fin de que sea un ensayo y no una anécdota.", "(생각하더니) 쓸 수 있겠네요. 매시간 온도를 재서 기록한다면요. 일화가 아니라 시험이 되도록."),
(P, "Maribel lo apunta todo. Hasta lo que como.", "마리벨은 다 적어요. 내가 뭘 먹는지까지."),
(M, "Solo cuando comes en el laboratorio, Pepe.", "실험실에서 먹을 때만이에요, 페페."),
(N, "(por primera vez, ríe) En la Politécnica tenía una profesora así. Me suspendió dos veces. Le debo media carrera.", "(처음으로 웃으며) 발렌시아 공대에 그런 교수님이 계셨어요. 저를 두 번이나 낙제시켰죠. 제 공부의 절반은 그분 덕이에요."),

("#", "Escena 4 · Viernes 4 de diciembre, 13:00 · Despacho de exportación", "장면 4 · 12월 4일 금요일 오후 1시 · 수출팀 사무실"),
(None, "Han pasado tres días de secadero. El palé de prueba ha salido entero, con un film nuevo que Paco encontró en un proveedor de Vila-real. En la pantalla del ordenador, dos correos sin abrir.", "건조기 구역에서 사흘이 지났다. 시험용 팔레트는 파코가 비야레알의 한 업체에서 찾아낸 새 필름으로 감싸 멀쩡하게 나왔다. 컴퓨터 화면에는 열지 않은 메일 두 통."),
(A, "Abre tú el de Denise. Yo no puedo.", "드니스 메일은 당신이 열어요. 난 못 하겠어요."),
(L, "«Resultado de la auditoría: aprobada. Una observación menor, cerrada con la acción correctiva del uno de diciembre». ¡Aprobada!", "'감사 결과: 승인. 경미한 지적 사항 하나, 12월 1일 시정 조치로 종결.' 승인이에요!"),
(A, "(se tapa la cara con las manos) Paco y su plantilla de cartón. Le voy a comprar un jamón.", "(두 손으로 얼굴을 가리며) 파코랑 그 판지 틀 덕분이네요. 하몬 하나 사 줘야겠어요."),
(L, "Hay más. «Consta en el informe la iniciativa de la cantonera interior, que recomendaremos a otros proveedores».", "더 있어요. '상자 안쪽 모서리 보호대에 대한 귀사의 착안을 보고서에 기재했으며, 다른 공급업체에도 권장할 예정임.'"),
(A, "O sea, que ahora somos un ejemplo. En septiembre éramos una esquina rota.", "그러니까 이제 우리가 본보기라는 거네요. 9월엔 깨진 모서리였는데."),
(L, "Ahora el de Noura. (respira) «Informe preliminar de inspección. Fábrica: conforme. Registros de calidad: conformes. Etiquetado en árabe: no conforme en la versión inicial; se ha verificado la versión corregida del día tres».", "이제 누라 메일. (숨을 들이쉬며) '예비 검사 보고서. 공장: 적합. 품질 기록: 적합. 아랍어 라벨: 초기본 부적합, 3일 자 수정본 확인 완료.'"),
(A, "¿Y?", "그리고요?"),
(L, "«Embalaje para clima cálido: ensayo aceptado a efectos de esta fase. Se recomienda repetirlo en cámara homologada antes del primer envío».", "'고온 기후용 포장: 이번 단계 목적상 시험 인정. 첫 선적 전 인증된 고온실에서 재시험 권장.'"),
(A, "Eso es casi un sí.", "그건 거의 '예'네요."),
(L, "Casi. Escucha el final: «Aprobación condicionada a la prueba de dilatación térmica del gran formato en el laboratorio de obra de Al-Rimal. Fecha propuesta: nueve y diez de diciembre».", "거의요. 끝부분 들어 봐요. '대형 규격의 열팽창 시험을 알리말 현장 실험동에서 실시하는 조건으로 승인. 제안 일정: 12월 9일과 10일.'"),
(A, "El miércoles que viene. En Riad.", "다음 주 수요일. 리야드에서."),
(L, "Con nuestras placas de Arena de Najd puestas en el suelo, y a cincuenta grados.", "우리 아레나 데 나지드 판을 바닥에 깔아 놓고, 50도로요."),
(A, "Pues habrá que llevar a alguien que sepa colocar.", "그럼 시공할 줄 아는 사람을 데려가야겠네요."),
(L, "La obra es de Iñaki. Él tiene cuadrillas.", "현장은 이냐키 거예요. 거기 시공팀이 있어요."),
(A, "Cuadrillas que no han tocado una placa de dos metros sesenta en su vida, apuesto. Me llevo la ficha de colocación. Y la llevo en papel.", "2미터 60짜리 판은 평생 만져 본 적 없는 시공팀이겠죠, 장담해요. 시공 지침서는 내가 챙길게요. 종이로요."),
(L, "¿Vienes? Creía que esta semana tenías a Sergio.", "같이 가요? 이번 주엔 세르히오 일이 있는 줄 알았는데."),
(A, "Sergio puede esperar. Una placa que se despega en Riad no espera a nadie.", "세르히오는 기다려도 돼요. 리야드에서 떨어지는 판은 아무도 기다려 주지 않아요."),
(L, "Llamo a Iñaki para que nos prepare la superficie. Hormigón curado, nivelado, y una cuadrilla el miércoles a las seis.", "이냐키한테 전화해서 바닥을 준비해 달라고 할게요. 양생 끝난 수평 콘크리트, 그리고 수요일 6시에 시공팀 하나."),
(A, "Y que no les dé el adhesivo más barato del almacén. Acuérdate de Monterrey.", "그리고 창고에서 제일 싼 접착제는 주지 말라고 해요. 몬테레이 기억하죠."),
(L, "Me acuerdo. Rodolfo y el suelo italiano que sonaba a hueco.", "기억해요. 로돌포랑, 텅 빈 소리가 나던 이탈리아 바닥."),
(A, "Pues eso. Que no nos pase lo mismo, y menos delante de Noura.", "바로 그거예요. 우리한테 똑같은 일이 생기면 안 돼요. 누라 앞에서는 더더욱."),
(L, "Le diré a Iñaki que nos guarde doce placas de Arena de Najd del envío de muestras. Con diez basta para el ensayo; dos, por si acaso.", "이냐키한테 샘플 선적분에서 아레나 데 나지드 판 열두 장을 남겨 두라고 할게요. 시험엔 열 장이면 되고, 두 장은 혹시 모르니까."),
(A, "Por si acaso. Ya hablas como Pepe.", "혹시 모르니까라. 이제 페페처럼 말하네요."),
(P, "(asoma la cabeza por la puerta) ¿Ya está? ¿Hemos aprobado?", "(문틈으로 고개를 내밀며) 끝났어? 우리 통과했어?"),
(L, "Una del todo. La otra, casi. Nos queda un examen en el desierto.", "하나는 완전히요. 다른 하나는 거의요. 사막에서 시험이 하나 남았어요."),
(P, "Pues decidle a esa ingeniera que las placas no tienen miedo al calor. Nacen a mil doscientos grados.", "그럼 그 엔지니어한테 말해. 판은 더위를 무서워하지 않는다고. 1,200도에서 태어나니까."),
(L, "Se lo diré. Pero ella me contestará: «No lo diga. Demuéstrelo».", "말할게요. 근데 그분은 이렇게 대답할 거예요. '말하지 말고 증명하세요.'"),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "리야드에서 돌아온 지 열흘. 같은 주에 감사관 두 명이 온다 공장을 찾는다. 빌드마트의 드니스는 암파로가, 사우디 검사관 누라는 루카스가 맡는다. 드니스는 애틀랜타에서 깨졌던 모서리를 다시 확인하고, 누라는 '보여 주고 싶은 것'이 아니라 '있는 그대로'를 보겠다고 한다. 그리고 아무도 읽지 못했던 아랍어 라벨에서 문제가 터진다. 마지막 남은 관문은 사막의 열이다.",
 "듣기 질문 ① 암파로가 매뉴얼에 없는 '안쪽 모서리 보호대'를 넣은 이유는? 드니스가 찾아낸 문제는 무엇이고, 어떻게 해결되는가?",
 "듣기 질문 ② 아랍어 라벨은 왜 읽을 수 없었는가? 누라는 그 원인을 무엇이라고 설명하는가?",
 "듣기 질문 ③ 누라의 예비 보고서 결과는? 승인의 마지막 조건은 무엇이고, 언제 어디서 이루어지는가?",
]),
]

